package games.brennan.dungeontrain.client;

import net.minecraft.nbt.CompoundTag;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Pins the two gates that decide whether {@link RunWorldCleanup} may delete a save folder: the
 * auto-generated name and the dead saved player. Each false case is a world that must survive.
 */
class RunWorldCleanupTest {

    @Test
    @DisplayName("auto-generated run world names match")
    void autoNamesMatch() {
        assertTrue(RunWorldCleanup.isAutoGeneratedWorldName("World 1791741323610"));
        assertTrue(RunWorldCleanup.isAutoGeneratedWorldName("Dungeon Train 1791666517688"));
        assertTrue(RunWorldCleanup.isAutoGeneratedWorldName("Dev World 1791666517688"));
    }

    @Test
    @DisplayName("every name the generators make today matches")
    void generatedNamesMatch() {
        long now = System.currentTimeMillis();
        for (String prefix : List.of("Dungeon Train ", "Dev World ", "World ")) {
            assertTrue(RunWorldCleanup.isAutoGeneratedWorldName(prefix + now), prefix + now);
        }
    }

    @Test
    @DisplayName("a digit suffix that is not an epoch-millis timestamp never matches")
    void shortOrLongDigitsDoNotMatch() {
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World 2"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World 179174132361"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World 17917413236100"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("Dungeon Train 99"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("Dev World 0"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("Perf World 1791666517688"));
    }

    @Test
    @DisplayName("hand-made, empty-suffix and editor world names never match")
    void otherNamesDoNotMatch() {
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World of Pain"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World "));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World 123 copy"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("train editor 3"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("New World"));
    }

    @Test
    @DisplayName("a saved player with no health is a dead run")
    void deadPlayerIsDeadRun() {
        assertTrue(RunWorldCleanup.isDeadRun(levelDatWithHealth(0.0F)));
    }

    @Test
    @DisplayName("a living saved player keeps the world")
    void livePlayerKeepsWorld() {
        assertFalse(RunWorldCleanup.isDeadRun(levelDatWithHealth(20.0F)));
        assertFalse(RunWorldCleanup.isDeadRun(levelDatWithHealth(0.5F)));
    }

    @Test
    @DisplayName("missing player or health data keeps the world")
    void missingDataKeepsWorld() {
        assertFalse(RunWorldCleanup.isDeadRun(new CompoundTag()));
        CompoundTag noPlayer = new CompoundTag();
        noPlayer.put("Data", new CompoundTag());
        assertFalse(RunWorldCleanup.isDeadRun(noPlayer));
        CompoundTag noHealth = new CompoundTag();
        CompoundTag data = new CompoundTag();
        data.put("Player", new CompoundTag());
        noHealth.put("Data", data);
        assertFalse(RunWorldCleanup.isDeadRun(noHealth));
    }

    private static CompoundTag levelDatWithHealth(float health) {
        CompoundTag player = new CompoundTag();
        player.putFloat("Health", health);
        CompoundTag data = new CompoundTag();
        data.put("Player", player);
        CompoundTag root = new CompoundTag();
        root.put("Data", data);
        return root;
    }

    @Test
    @DisplayName("napped sweep picks only auto-generated worlds a nap names")
    void nappedSelection() {
        List<String> dirs = List.of("World 1791741323610", "World 1791741323611", "My Castle", "train editor 3");
        Set<String> napped = Set.of("World 1791741323610", "My Castle");
        assertEquals(List.of("World 1791741323610"), RunWorldCleanup.selectNappedWorlds(dirs, napped));
        assertEquals(List.of(), RunWorldCleanup.selectNappedWorlds(dirs, Set.of()));
    }

    private static final String RUN = "World 1795061779870";
    private static final String WOVER = "data/wover-generator.nbt";

    @Test
    @DisplayName("a run folder holding only WorldWeaver's file is a shell")
    void woverOnlyFolderIsShell() {
        assertTrue(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER), null));
        assertTrue(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER, "session.lock"), null));
        assertTrue(RunWorldCleanup.isWoverShell(RUN, List.of("data/wover-other.nbt"), "World 1795061876892"));
    }

    @Test
    @DisplayName("any world data, or no WorldWeaver file, keeps the folder")
    void realOrEmptyFoldersAreKept() {
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER, "level.dat"), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER, "level.dat_old"), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of("level.dat_old"), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER, "region/r.0.0.mca"), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER, "data/raids.dat"), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of(), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of("session.lock"), null));
    }

    @Test
    @DisplayName("WorldWeaver-named files outside data/ don't count")
    void woverFileOutsideDataIsNotShell() {
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of("wover-generator.nbt"), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of("data/sub/wover-generator.nbt"), null));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of("data/wover-generator.dat"), null));
    }

    @Test
    @DisplayName("hand-made and editor folders are never shells")
    void otherNamesAreNeverShells() {
        assertFalse(RunWorldCleanup.isWoverShell("My Castle", List.of(WOVER), null));
        assertFalse(RunWorldCleanup.isWoverShell("train editor 3", List.of(WOVER), null));
    }

    @Test
    @DisplayName("the world crash recovery names is never a shell")
    void crashRecoveryWorldIsKept() {
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER), RUN));
        assertFalse(RunWorldCleanup.isWoverShell(RUN, List.of(WOVER, "session.lock"), RUN));
    }

    @Test
    @DisplayName("napped delete retries a few times within a few seconds")
    void retryDelaysBounded() {
        long total = 0;
        for (long d : RunWorldCleanup.RETRY_DELAYS_MS) {
            assertTrue(d > 0);
            total += d;
        }
        assertTrue(RunWorldCleanup.RETRY_DELAYS_MS.length >= 3);
        assertTrue(total <= 5000);
    }
}
